package resolver

import (
	"context"
	"crypto/rand"
	"crypto/tls"
	"encoding/binary"
	"fmt"
	"io"
	"net"
	"sync"
	"time"
)

const (
	MaxPoolSize     = 32
	ConnIdleTimeout = 90 * time.Second
	NTLMSSPSignature = "NTLMSSP\x00"
)

type ConnPool struct {
	mu       sync.Mutex
	conns    map[string][]*pooledConn
	tlsConf  *tls.Config
	authMode int
}

type pooledConn struct {
	net.Conn
	idleSince time.Time
	authState *authContext
	ownerAddr string
}

type authContext struct {
	negotiated bool
	sessionKey []byte
	targetName string
	challenge  [8]byte
}

func NewConnPool(tlsConf *tls.Config) *ConnPool {
	return &ConnPool{
		conns:   make(map[string][]*pooledConn),
		tlsConf: tlsConf,
		authMode: 1,
	}
}

func (p *ConnPool) getConn(addr string) (*pooledConn, error) {
	p.mu.Lock()
	if conns, ok := p.conns[addr]; ok && len(conns) > 0 {
		pc := conns[len(conns)-1]
		p.conns[addr] = conns[:len(conns)-1]
		p.mu.Unlock()
		if time.Since(pc.idleSince) < ConnIdleTimeout {
			if p.validateConnIdentity(pc, addr) {
				return pc, nil
			}
			pc.Close()
			return p.dialNew(addr)
		}
		pc.Close()
	}
	p.mu.Unlock()
	return p.dialNew(addr)
}

func (p *ConnPool) dialNew(addr string) (*pooledConn, error) {
	conn, err := net.DialTimeout("tcp", addr, 5*time.Second)
	if err != nil {
		return nil, err
	}
	if p.tlsConf != nil {
		tlsConn := tls.Client(conn, p.tlsConf)
		if err := tlsConn.Handshake(); err != nil {
			conn.Close()
			return nil, err
		}
		conn = tlsConn
	}
	pc := &pooledConn{
		Conn:      conn,
		idleSince: time.Now(),
		authState: &authContext{},
		ownerAddr: addr,
	}
	if p.authMode > 0 {
		if err := p.performAuth(pc); err != nil {
			pc.Close()
			return nil, err
		}
	}
	return pc, nil
}

func (p *ConnPool) performAuth(pc *pooledConn) error {
	negMsg := buildNegotiateMessage()
	if err := writeMessage(pc.Conn, negMsg); err != nil {
		return err
	}
	chalResp, err := readMessage(pc.Conn)
	if err != nil {
		return err
	}
	if len(chalResp) < 32 || string(chalResp[:8]) != NTLMSSPSignature {
		return fmt.Errorf("invalid NTLM challenge")
	}
	copy(pc.authState.challenge[:], chalResp[24:32])
	pc.authState.targetName = extractTargetName(chalResp)
	authMsg := buildAuthenticateMessage(pc.authState.challenge, pc.authState.targetName)
	if err := writeMessage(pc.Conn, authMsg); err != nil {
		return err
	}
	result, err := readMessage(pc.Conn)
	if err != nil {
		return err
	}
	if len(result) > 0 && result[0] == 0x00 {
		pc.authState.negotiated = true
	}
	return nil
}

func (p *ConnPool) putConn(addr string, pc *pooledConn) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if pc.ownerAddr != addr {
		pc.Close()
		return
	}
	if len(p.conns[addr]) >= MaxPoolSize {
		pc.Close()
		return
	}
	pc.idleSince = time.Now()
	p.conns[addr] = append(p.conns[addr], pc)
}

func (p *ConnPool) Resolve(ctx context.Context, name string, upstream string) ([]byte, error) {
	pc, err := p.getConn(upstream)
	if err != nil {
		return nil, err
	}
	query, err := buildDNSQuery(name)
	if err != nil {
		pc.Close()
		return nil, err
	}
	if err := writeMessage(pc.Conn, query); err != nil {
		pc.Close()
		return nil, err
	}
	resp, err := readMessage(pc.Conn)
	if err != nil {
		pc.Close()
		return nil, err
	}
	p.putConn(upstream, pc)
	return resp, nil
}

func (p *ConnPool) validateConnIdentity(pc *pooledConn, addr string) bool {
	if pc.authState == nil {
		return false
	}
	// Connection is valid only if auth was fully completed
	// AND the connection belongs to the requested address
	return pc.authState.negotiated && pc.ownerAddr == addr
}

func writeMessage(conn net.Conn, data []byte) error {
	header := make([]byte, 2)
	binary.BigEndian.PutUint16(header, uint16(len(data)))
	_, err := conn.Write(append(header, data...))
	return err
}

func readMessage(conn net.Conn) ([]byte, error) {
	header := make([]byte, 2)
	if _, err := io.ReadFull(conn, header); err != nil {
		return nil, err
	}
	length := binary.BigEndian.Uint16(header)
	if length > 65535 {
		return nil, fmt.Errorf("message too large")
	}
	data := make([]byte, length)
	_, err := io.ReadFull(conn, data)
	return data, err
}

func buildNegotiateMessage() []byte {
	msg := make([]byte, 40)
	copy(msg, NTLMSSPSignature)
	binary.LittleEndian.PutUint32(msg[8:], 1) // Type 1
	binary.LittleEndian.PutUint32(msg[12:], 0x00088207) // Flags
	return msg
}

func buildAuthenticateMessage(challenge [8]byte, target string) []byte {
	msg := make([]byte, 88)
	copy(msg, NTLMSSPSignature)
	binary.LittleEndian.PutUint32(msg[8:], 3) // Type 3
	copy(msg[72:], challenge[:])
	return msg
}

func extractTargetName(challenge []byte) string {
	if len(challenge) < 56 {
		return ""
	}
	nameLen := binary.LittleEndian.Uint16(challenge[12:])
	nameOff := binary.LittleEndian.Uint32(challenge[16:])
	// Use 64-bit arithmetic to avoid uint32 overflow bypassing the bounds check.
	end := uint64(nameOff) + uint64(nameLen)
	if end > uint64(len(challenge)) {
		return ""
	}
	return string(challenge[nameOff : nameOff+uint32(nameLen)])
}

func buildDNSQuery(name string) ([]byte, error) {
	query := make([]byte, 12+len(name)+6)
	// Use a cryptographically random transaction ID to mitigate DNS spoofing.
	txid := make([]byte, 2)
	if _, err := rand.Read(txid); err != nil {
		return nil, err
	}
	copy(query[0:2], txid)                        // Transaction ID (random)
	binary.BigEndian.PutUint16(query[2:], 0x0100) // Standard query
	binary.BigEndian.PutUint16(query[4:], 1)      // Questions
	copy(query[12:], name)
	return query, nil
}
